3	import (
4		"encoding/json"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	// ---- plans
11	
12	// CreatePlan adds a plan. UsageType defaults to Licensed; a new plan is active.
13	func (s *Store) CreatePlan(p Plan, now time.Time) (Plan, error) {
14		p.Name = strings.TrimSpace(p.Name)
15		if p.UsageType == "" {
16			p.UsageType = Licensed
17		}
18		p.Active = true
19		if err := checkPlan(p); err != nil {
20			return Plan{}, err
21		}
22		s.mu.Lock()
23		defer s.mu.Unlock()
24		if _, ok := s.orgs[p.OrgID]; !ok {
25			return Plan{}, ErrNotFound
26		}
27		p.ID = s.newID("plan")
28		p.CreatedAt = now.UTC()
29		s.plans[p.ID] = p
30		return p, nil
31	}
32	
33	func checkPlan(p Plan) error {
34		switch {
35		case p.Name == "":
36			return invalid("a plan needs a name")
37		case !p.Currency.Valid():
38			return invalid("unknown currency %q", p.Currency)
39		case p.UnitAmount < 0:
40			return invalid("a plan's price cannot be negative")
41		case p.Interval != Monthly && p.Interval != Yearly:
42			return invalid("a plan bills every month or every year")
43		case p.UsageType != Licensed && p.UsageType != Metered:
44			return invalid("a plan is licensed or metered")
45		case p.TrialDays < 0 || p.TrialDays > 365:
46			return invalid("a trial lasts 0 to 365 days")
47		}
48		return nil
49	}
50	
51	// Plan returns one of an organization's plans.
52	func (s *Store) Plan(orgID, id string) (Plan, bool) {
53		s.mu.Lock()
54		defer s.mu.Unlock()
55		p, ok := s.plans[id]
56		if !ok || p.OrgID != orgID {
57			return Plan{}, false
58		}
59		return p, true
60	}
61	
62	// Plans returns an organization's plans, oldest first.
63	func (s *Store) Plans(orgID string) []Plan {
64		s.mu.Lock()
65		defer s.mu.Unlock()
66		out := []Plan{}
67		for _, p := range s.plans {
68			if p.OrgID == orgID {
69				out = append(out, p)
70			}
71		}
72		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
73		return out
74	}
75	
76	// UpdatePlan changes a plan with f. Its currency, price, interval and usage type cannot change once created: subscriptions
77	// depend on them.
78	func (s *Store) UpdatePlan(orgID, id string, f func(*Plan) error) (Plan, error) {
79		s.mu.Lock()
80		defer s.mu.Unlock()
81		old, ok := s.plans[id]
82		if !ok || old.OrgID != orgID {
83			return Plan{}, ErrNotFound
84		}
85		p := old
86		if err := f(&p); err != nil {
87			return Plan{}, err
88		}
89		p.ID, p.OrgID, p.CreatedAt = old.ID, old.OrgID, old.CreatedAt
90		p.Currency, p.UnitAmount, p.Interval, p.UsageType = old.Currency, old.UnitAmount, old.Interval, old.UsageType
91		p.Name = strings.TrimSpace(p.Name)
92		if err := checkPlan(p); err != nil {
93			return Plan{}, err
94		}
95		s.plans[id] = p
96		return p, nil
97	}
98	
99	// ---- subscriptions
100	
101	// CreateSubscription stores a new subscription. The caller sets its status and periods.
102	func (s *Store) CreateSubscription(sub Subscription, now time.Time) (Subscription, error) {
103		if sub.Quantity <= 0 {
104			return Subscription{}, invalid("the quantity must be at least 1")
105		}
106		if sub.DiscountPercent < 0 || sub.DiscountPercent > 100 {
107			return Subscription{}, invalid("the discount is 0 to 100 percent")
108		}
109		s.mu.Lock()
110		defer s.mu.Unlock()
111		if _, ok := s.customers[sub.CustomerID]; !ok {
112			return Subscription{}, ErrNotFound
113		}
114		if p, ok := s.plans[sub.PlanID]; !ok || p.OrgID != sub.OrgID {
115			return Subscription{}, ErrNotFound
116		}
117		sub.ID = s.newID("sub")
118		sub.CreatedAt = now.UTC()
119		s.subs[sub.ID] = sub
120		return copySub(sub), nil
121	}
122	
123	// Subscription returns one of an organization's subscriptions.
124	func (s *Store) Subscription(orgID, id string) (Subscription, bool) {
125		s.mu.Lock()
126		defer s.mu.Unlock()
127		sub, ok := s.subs[id]
128		if !ok || sub.OrgID != orgID {
129			return Subscription{}, false
130		}
131		return copySub(sub), true
132	}
133	
134	// SubscriptionFilter narrows Subscriptions.
135	type SubscriptionFilter struct {
136		CustomerID string
137		Status     SubStatus
138	}
139	
140	// Subscriptions returns an organization's subscriptions that match f, oldest first.
141	func (s *Store) Subscriptions(orgID string, f SubscriptionFilter) []Subscription {
142		s.mu.Lock()
143		defer s.mu.Unlock()
144		out := []Subscription{}
145		for _, sub := range s.subs {
146			if sub.OrgID != orgID || (f.CustomerID != "" && sub.CustomerID != f.CustomerID) || (f.Status != "" && sub.Status != f.Status) {
147				continue
148			}
149			out = append(out, copySub(sub))
150		}
151		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
152		return out
153	}
154	
155	// UpdateSubscription changes a subscription with f, which may refuse with an error.
156	func (s *Store) UpdateSubscription(orgID, id string, f func(*Subscription) error) (Subscription, error) {
157		s.mu.Lock()
158		defer s.mu.Unlock()
159		old, ok := s.subs[id]
160		if !ok || old.OrgID != orgID {
161			return Subscription{}, ErrNotFound
162		}
163		sub := copySub(old)
164		if err := f(&sub); err != nil {
165			return Subscription{}, err
166		}
167		sub.ID, sub.OrgID, sub.CustomerID, sub.CreatedAt = old.ID, old.OrgID, old.CustomerID, old.CreatedAt
168		if sub.Quantity <= 0 {
169			return Subscription{}, invalid("the quantity must be at least 1")
170		}
171		if p, ok := s.plans[sub.PlanID]; !ok || p.OrgID != orgID {
172			return Subscription{}, ErrNotFound
173		}
174		s.subs[id] = sub
175		return copySub(sub), nil
176	}
177	
178	// DueSubscriptions returns the subscriptions of every organization whose current period has ended by now and that are not
179	// canceled, the longest overdue first.
180	func (s *Store) DueSubscriptions(now time.Time) []Subscription {
181		s.mu.Lock()
182		defer s.mu.Unlock()
183		out := []Subscription{}
184		for _, sub := range s.subs {
185			if sub.Status != Canceled && !sub.CurrentPeriodEnd.After(now) {
186				out = append(out, copySub(sub))
187			}
188		}
189		sort.Slice(out, func(i, j int) bool {
190			if !out[i].CurrentPeriodEnd.Equal(out[j].CurrentPeriodEnd) {
191				return out[i].CurrentPeriodEnd.Before(out[j].CurrentPeriodEnd)
192			}
193			return out[i].ID < out[j].ID
194		})
195		return out
196	}
197	
198	func copySub(sub Subscription) Subscription {
199		if sub.TrialEnd != nil {
200			t := *sub.TrialEnd
201			sub.TrialEnd = &t
202		}
203		if sub.CanceledAt != nil {
204			t := *sub.CanceledAt
205			sub.CanceledAt = &t
206		}
207		return sub
208	}
209	
210	// AddUsage records usage of a subscription to a metered plan at time at.
211	func (s *Store) AddUsage(orgID, subID string, quantity int64, at, now time.Time) (UsageRecord, error) {
212		if quantity <= 0 {
213			return UsageRecord{}, invalid("usage must be a positive quantity")
214		}
215		s.mu.Lock()
216		defer s.mu.Unlock()
217		sub, ok := s.subs[subID]
218		if !ok || sub.OrgID != orgID {
219			return UsageRecord{}, ErrNotFound
220		}
221		if p := s.plans[sub.PlanID]; p.UsageType != Metered {
222			return UsageRecord{}, invalid("the subscription's plan is not metered")
223		}
224		u := UsageRecord{ID: s.newID("use"), OrgID: orgID, SubscriptionID: subID, Quantity: quantity, At: at.UTC(), CreatedAt: now.UTC()}
225		s.usage = append(s.usage, u)
226		return u, nil
227	}
228	
229	// UsageTotal adds up a subscription's usage at times in [from, to).
230	func (s *Store) UsageTotal(orgID, subID string, from, to time.Time) int64 {
231		s.mu.Lock()
232		defer s.mu.Unlock()
233		var n int64
234		for _, u := range s.usage {
235			if u.OrgID == orgID && u.SubscriptionID == subID && !u.At.Before(from) && u.At.Before(to) {
236				n += u.Quantity
237			}
238		}
239		return n
240	}
