114	// Response is the server's answer.
115	type Response struct {
116		Code   int
117		Header http.Header
118		Body   []byte
119	}
120	
121	// JSON decodes the body into v, failing the test when it cannot.
122	func (r *Response) JSON(t testing.TB, v any) {
123		t.Helper()
124		if err := json.Unmarshal(r.Body, v); err != nil {
125			t.Fatalf("response %d is not the JSON expected: %v\n%s", r.Code, err, r.Body)
126		}
127	}
128	
129	// Map decodes the body as a JSON object.
130	func (r *Response) Map(t testing.TB) map[string]any {
131		t.Helper()
132		var m map[string]any
133		r.JSON(t, &m)
134		return m
135	}
136	
137	// String is the status and body, for failure messages.
138	func (r *Response) String() string { return fmt.Sprintf("%d %s", r.Code, bytes.TrimSpace(r.Body)) }
139	
140	// Do sends a request to the server with key as its API key ("" for none). A body that is a string or []byte is sent as it
141	// is; any other non-nil body is sent as JSON.
142	func (e *Env) Do(method, path, key string, body any) *Response {
143		e.T.Helper()
144		return e.DoWith(method, path, key, body, nil)
145	}
146	
147	// DoWith is Do with extra request headers.
148	func (e *Env) DoWith(method, path, key string, body any, header http.Header) *Response {
149		e.T.Helper()
150		var rd io.Reader
151		switch b := body.(type) {
152		case nil:
153		case string:
154			rd = strings.NewReader(b)
155		case []byte:
156			rd = bytes.NewReader(b)
157		default:
158			raw, err := json.Marshal(b)
159			if err != nil {
160				e.T.Fatal(err)
161			}
162			rd = bytes.NewReader(raw)
163		}
164		req := httptest.NewRequest(method, path, rd)
165		if key != "" {
166			req.Header.Set("Authorization", "Bearer "+key)
167		}
168		for k, vs := range header {
169			for _, v := range vs {
170				req.Header.Add(k, v)
171			}
172		}
173		rec := httptest.NewRecorder()
174		e.Server.ServeHTTP(rec, req)
175		return &Response{Code: rec.Code, Header: rec.Header(), Body: rec.Body.Bytes()}
176	}
177	
178	// MustDo is Do that fails the test unless the answer has the status want, and decodes the body into out (when not nil).
179	func (e *Env) MustDo(want int, method, path, key string, body, out any) *Response {
180		e.T.Helper()
181		r := e.Do(method, path, key, body)
182		if r.Code != want {
183			e.T.Fatalf("%s %s: want %d, got %s", method, path, want, r)
184		}
185		if out != nil {
186			r.JSON(e.T, out)
187		}
188		return r
189	}
