func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) (bool, error) {
	plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
	if !ok {
		return false, store.ErrNotFound
	}
	if sub.CancelAtPeriodEnd {
		end := sub.CurrentPeriodEnd
		canceled, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
			if x.Status == store.Canceled || !x.CurrentPeriodEnd.Equal(end) {
				return store.ErrStale
			}
			x.Status, x.CanceledAt = store.Canceled, &end
			return nil
		})
		switch {
		case errors.Is(err, store.ErrStale):
			return false, nil
		case err != nil:
			return false, err
		}
		s.publish(ctx, sub.OrgID, "subscription.canceled", canceled)
		return true, nil
	}
	start := now
	end := billing.AddInterval(start, plan.Interval)
	var draft *store.Invoice
	switch {
	case plan.UsageType == store.Metered && sub.Status != store.Trialing:
		inv := s.periodInvoice(sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
		draft = &inv
	case plan.UsageType == store.Licensed:
		inv := s.periodInvoice(sub, plan, start, end)
		draft = &inv
	}
	next, inv, err := s.Store.Renew(sub.OrgID, sub.ID, store.Renewal{FromEnd: sub.CurrentPeriodEnd, PeriodStart: start, PeriodEnd: end, Invoice: draft}, now)
	switch {
	case errors.Is(err, store.ErrStale):
		return false, nil
	case err != nil:
		return false, err
	}
	paid, payErr := true, error(nil)
	if inv != nil {
		s.publish(ctx, next.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": next.ID})
		paid, payErr = s.chargeInvoice(ctx, next.OrgID, inv.ID)
	}
	status := next.Status
	switch {
	case payErr != nil:
		// The gateway could not take the money: the invoice stays open and the status stays as it was.
	case paid:
		status = store.Active
	default:
		status = store.PastDue
	}
	next, err = s.Store.UpdateSubscription(next.OrgID, next.ID, func(x *store.Subscription) error {
		x.Status = status
		return nil
	})
	if err != nil {
		return true, err
	}
	s.publish(ctx, next.OrgID, "subscription.updated", next)
	if payErr != nil {
		return true, fmt.Errorf("charge invoice %s: %w", inv.ID, payErr)
	}
	return true, nil
}

