	sub := createSub(e, c, p)
	end := sub.CurrentPeriodEnd
	next := end.AddDate(0, 1, 0)
	renewal := func(from, start, stop time.Time) store.Renewal {
		ps, pe := start, stop
		inv := &store.Invoice{OrgID: e.Acme.ID, CustomerID: c.ID, SubscriptionID: sub.ID, Currency: money.USD, PeriodStart: &ps, PeriodEnd: &pe}
		return store.Renewal{FromEnd: from, PeriodStart: start, PeriodEnd: stop, Invoice: inv}
	}
	if _, inv, err := e.Store.Renew(e.Acme.ID, sub.ID, renewal(end, end, next), end); err != nil || inv == nil {
		t.Fatalf("first renewal = %v, %v", inv, err)
	}
	// Renewing from the old period again is stale, and so is a renewal that would invoice the same period start again.
	if _, _, err := e.Store.Renew(e.Acme.ID, sub.ID, renewal(end, end, next), end); !errors.Is(err, store.ErrStale) {
		t.Fatalf("renewing from the old period: %v, want ErrStale", err)
	}
	if _, _, err := e.Store.Renew(e.Acme.ID, sub.ID, renewal(next, next, next.AddDate(0, 1, 0)), end); !errors.Is(err, store.ErrStale) {
		t.Fatalf("invoicing the same period start twice: %v, want ErrStale", err)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 2 {
		t.Fatalf("invoices = %d, want the first one and one renewal", len(invs))
	}
}

args.old_string:
